insert into public.questions (subject, grade, prompt, choices, correct_index, sort_order) values
('2a5 - Main Idea','G2', $p$"Please read a book before you go to bed," said Mother. Tom picked a book from his bookshelf and went to bed. Two minutes later, Mother went to kiss him goodnight, but she found Tom already asleep.  This story mainly tells:$p$, $c$["that Tom didn't like to read books","that Tom usually goes to bed late","that Tom fell asleep quickly"]$c$::jsonb, 2, 1),
('2a5 - Main Idea','G2', $p$Judy and Tom ran to the trees. There were many people in the orchard. Judy picked only red apples. Tom tried to pick large apples. They had a good time.  This story mainly tells:$p$, $c$["that people don't like apples","that Tom only played in apple trees","that Judy and Tom went apple picking"]$c$::jsonb, 2, 2),
('2a5 - Main Idea','G2', $p$"Oh, what a cute monkey! But its cage is too small," said Judy to her friends. They went to see a rainforest and some animals in a building nearby. "I wish I could take them out of their cages. Animals in cages look so sad to me," said Judy.  This story mainly tells:$p$, $c$["that the animals in the cages were dangerous","that Judy felt pity for the animals in the cages","that Judy played with the animals in the cages"]$c$::jsonb, 1, 3),
('2a5 - Main Idea','G2', $p$A new boy came to Tom's class. He sat next to Tom. "After school, can you come to my house?" asked Tom. "We can do our homework together, and then play in the park."  This story mainly tells:$p$, $c$["that Tom wanted this new boy to come to his house","that this new boy didn't want to go to Tom's house","that Tom didn't want to invite this new boy to his house"]$c$::jsonb, 0, 4),
('2a5 - Main Idea','G2', $p$"Mom, do you know what happened in my class?" asked Judy. During dinner Judy always talks about her school day, her friends, and her teacher. Her mother and father like to listen to Judy.  This story mainly tells:$p$, $c$["that her mother and father don't want to listen to Judy","that Judy likes to talk about her day at dinner","that Judy doesn't talk about her friends"]$c$::jsonb, 1, 5),
('2a5 - Main Idea','G2', $p$"I want to go to the petting zoo again," said Judy, with a smile. "You went there last Saturday," said her mother. Judy likes to pet the little animals in the cages. They ate food out of Judy's hand. Judy wants to see the cute animals again this Saturday.  This story mainly tells:$p$, $c$["that Judy wants to go to the petting zoo again","that Judy wants to have a pet","that Judy prepares food at home for the animals"]$c$::jsonb, 0, 6);
insert into public.questions (subject, grade, prompt, choices, correct_index, sort_order) values
('2a6 - Main Idea','G2', $p$One day Mr. Wilson was playing golf in his back yard. He hit the ball a little too hard. It went over the fence and broke one of Mr. Smith's windows.  This story mainly tells:$p$, $c$["how to play golf","why we have fences","how Mr. Wilson broke Mr. Smith's window"]$c$::jsonb, 2, 1),
('2a6 - Main Idea','G2', $p$Raccoons are great at climbing trees. Sometimes, they make their homes in hollow trees. They eat almost anything that comes along like frogs, small turtles, berries and fruits. If there is water nearby, they will sometimes wash their food in it or even play around in the water.  This story mainly tells:$p$, $c$["why trees are hollow","how raccoons climb trees","about how raccoons behave"]$c$::jsonb, 2, 2),
('2a6 - Main Idea','G2', $p$Many farmers have cows. Cows give us fresh milk. We also get meat from their flesh. Most good leather comes from a cow's skin.  This story mainly tells:$p$, $c$["how to raise a cow","what to feed a cow","how cows are useful animals"]$c$::jsonb, 2, 3),
('2a6 - Main Idea','G2', $p$One day, a fox got his tail caught in a trap. He wanted to keep his tail, but in order to get free, he had to leave his tail behind.  This story mainly tells:$p$, $c$["how the fox got a tail","how the fox lost his tail","why foxes have long tails"]$c$::jsonb, 1, 4),
('2a6 - Main Idea','G2', $p$Dinosaurs lived many years ago. Some were very big. Others were smaller than dogs and cats. Dinosaurs were real animals. There are no dinosaurs alive today. You can see what they looked like if you go to the museum.  This story mainly tells:$p$, $c$["about dinosaurs","why dinosaurs are not alive today","that all dinosaurs were very big"]$c$::jsonb, 0, 5),
('2a6 - Main Idea','G2', $p$Sally and Lucy play together every afternoon. They play hopscotch. They play dress-up. They play with their dolls. They tell each other many stories. They are good friends.  This story mainly tells:$p$, $c$["that Sally and Lucy like to talk","what Sally and Lucy do together","that Sally and Lucy don't play together"]$c$::jsonb, 1, 6);
insert into public.questions (subject, grade, prompt, choices, correct_index, sort_order) values
('2a7 - Main Idea','G2', $p$Long ago, people did not have sugar. To make something sweeter, they used honey. Today, some people still put honey in their tea.  This story mainly tells:$p$, $c$["that honey was once used instead of sugar","where honey comes from","why some people like honey more than sugar"]$c$::jsonb, 0, 1),
('2a7 - Main Idea','G2', $p$For the first year, a baby horse is called a foal. After that, a male horse is called a colt. A female horse is called a filly. Horses are fully grown when they are four years old.  This story mainly tells:$p$, $c$["how male horses behave differently","how horses are named differently as they grow","how female horses behave differently"]$c$::jsonb, 1, 2),
('2a7 - Main Idea','G2', $p$There are many kinds of butterflies. Butterflies are beautiful, large insects. They have four pretty wings. They have six legs. They also have two feelers and a long thin body.  This story mainly tells:$p$, $c$["why butterflies are insects","why butterflies have wings","what butterflies look like"]$c$::jsonb, 2, 3),
('2a7 - Main Idea','G2', $p$There are many kinds of moths. A moth looks a lot like a butterfly. It is also an insect. It also has four wings. It also has two feelers. But its feelers are fuzzy. Its body is long, flat, and fuzzy.  This story mainly tells:$p$, $c$["why moths are fuzzy","what a moth looks like","that a moth has four wings"]$c$::jsonb, 1, 4),
('2a7 - Main Idea','G2', $p$Fish do not have eyelids, so they cannot close their eyes when they sleep. They sleep with their eyes open. They do not see while they are sleeping. They keep moving their fins while they sleep, but stay in one place. They lie on their bellies or on their sides.  This story mainly tells:$p$, $c$["that fish do not sleep","that fish do not see","how fish sleep"]$c$::jsonb, 2, 5),
('2a7 - Main Idea','G2', $p$Outside my window, I can hear the birds chirping. Male birds sing a lot. They sing to female birds. They sing to keep other male birds away. Sometimes, they sing because they are happy. Female birds do not sing much.  This story mainly tells:$p$, $c$["that female birds do not sing as much","why male birds sing","that birds chirp when they are frightened"]$c$::jsonb, 1, 6);
