insert into public.questions (subject, grade, prompt, choices, correct_index, sort_order) values
('2a9 - Sequence','G2', $p$Choose the best order. A. The snowman's eyes were buttons. His nose was a carrot. His mouth was two sticks. B. Tara and Ted were playing outdoors in the snow. C. They made a little snowman.$p$, $c$["B-A-C","C-A-B","B-C-A"]$c$::jsonb, 2, 1),
('2a9 - Sequence','G2', $p$Choose the best order. A. "How old will Tom be?" asked Penny's big sister, Donna. B. "Seven," said Penny. C. Penny said, "I'm going to Tom's birthday party tomorrow."$p$, $c$["A-B-C","A-C-B","C-A-B"]$c$::jsonb, 2, 2),
('2a9 - Sequence','G2', $p$Choose the best order. A. Frogs and turtles can live in the water. B. These animals that live on land and in the water can walk and swim. C. But they can live on land, too.$p$, $c$["A-B-C","A-C-B","B-A-C"]$c$::jsonb, 1, 3),
('2a9 - Sequence','G2', $p$Choose the best order. A. It makes wind. B. It can also make kites fly. C. Sometimes, air moves very fast. D. The wind can blow things away.$p$, $c$["C-A-D-B","D-B-C-A","C-A-B-D"]$c$::jsonb, 0, 4),
('2a9 - Sequence','G2', $p$Choose the best order. A. Farmers gather the eggs soon after they are laid. B. Some chickens are raised for their eggs. C. Eggs must be kept in a cool place to keep them from spoiling.$p$, $c$["B-C-A","B-A-C","A-B-C"]$c$::jsonb, 1, 5),
('2a9 - Sequence','G2', $p$Choose the best order. A. After twenty days, they will move again. B. Every twenty days, the group moves to a new place to live. C. Army ants never stay in one place for a long time.$p$, $c$["C-B-A","C-A-B","B-A-C"]$c$::jsonb, 0, 6),
